//! Spatial indexing for efficient region queries.
//!
//! Uses an R*-tree to enable O(log n) queries for:
//! - Finding all entities in a rectangular region
//! - Finding entities at a specific point
//! - Finding entities that might overlap with a given entity
//!
//! This is essential for:
//! - DRC (Design Rule Check) - finding nearby objects to check clearances
//! - Rendering - only drawing visible objects
//! - Selection - finding objects under cursor

use bevy_ecs::prelude::*;
use rstar::{RTree, RTreeObject, AABB};

use cypcb_core::Point;

/// An entry in the spatial index.
///
/// Associates an entity with its bounding box and layer information.
/// The layer mask allows filtering queries by copper layer.
#[derive(Debug, Clone)]
pub struct SpatialEntry {
    /// The ECS entity this entry represents.
    pub entity: Entity,
    /// The axis-aligned bounding box in nanometers.
    pub envelope: AABB<[i64; 2]>,
    /// Bit mask of layers this entity occupies (bit 0 = layer 0, etc.).
    pub layer_mask: u32,
}

impl SpatialEntry {
    /// Create a new spatial entry.
    ///
    /// # Arguments
    ///
    /// * `entity` - The ECS entity
    /// * `min` - Minimum corner of bounding box
    /// * `max` - Maximum corner of bounding box
    /// * `layer_mask` - Bit mask of occupied layers
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::prelude::*;
    /// use cypcb_world::SpatialEntry;
    /// use cypcb_core::Point;
    ///
    /// // Create an entry for a component on top layer only
    /// let entry = SpatialEntry::new(
    ///     Entity::from_raw(0),
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 10.0),
    ///     0b01,  // Top layer only
    /// );
    /// ```
    pub fn new(entity: Entity, min: Point, max: Point, layer_mask: u32) -> Self {
        SpatialEntry {
            entity,
            envelope: AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]),
            layer_mask,
        }
    }

    /// Create an entry from raw coordinates.
    pub fn from_raw(entity: Entity, min_x: i64, min_y: i64, max_x: i64, max_y: i64, layer_mask: u32) -> Self {
        SpatialEntry {
            entity,
            envelope: AABB::from_corners([min_x, min_y], [max_x, max_y]),
            layer_mask,
        }
    }

    /// Check if this entry overlaps with a specific layer.
    #[inline]
    pub fn on_layer(&self, layer: u8) -> bool {
        self.layer_mask & (1 << layer) != 0
    }

    /// Check if this entry shares any layers with the given mask.
    #[inline]
    pub fn layers_overlap(&self, mask: u32) -> bool {
        self.layer_mask & mask != 0
    }
}

impl RTreeObject for SpatialEntry {
    type Envelope = AABB<[i64; 2]>;

    fn envelope(&self) -> Self::Envelope {
        self.envelope
    }
}

/// R*-tree spatial index for efficient region queries.
///
/// Wraps an rstar `RTree` to provide O(log n) spatial queries.
/// The index is rebuilt after batch updates rather than supporting
/// incremental insertion, which is more efficient for the typical
/// "parse file, build world" workflow.
///
/// # Examples
///
/// ```
/// use bevy_ecs::prelude::*;
/// use cypcb_world::{SpatialIndex, SpatialEntry};
/// use cypcb_core::Point;
///
/// let mut index = SpatialIndex::new();
///
/// // Create some entries
/// let entries = vec![
///     SpatialEntry::new(
///         Entity::from_raw(0),
///         Point::from_mm(0.0, 0.0),
///         Point::from_mm(10.0, 10.0),
///         0b01,
///     ),
///     SpatialEntry::new(
///         Entity::from_raw(1),
///         Point::from_mm(5.0, 5.0),
///         Point::from_mm(15.0, 15.0),
///         0b01,
///     ),
/// ];
///
/// // Bulk load for efficiency
/// index.rebuild(entries);
///
/// // Query a region
/// let found: Vec<_> = index.query_region(
///     Point::from_mm(4.0, 4.0),
///     Point::from_mm(6.0, 6.0),
/// ).collect();
/// assert_eq!(found.len(), 2); // Both entries overlap
/// ```
#[derive(Resource, Default)]
pub struct SpatialIndex {
    tree: RTree<SpatialEntry>,
}

impl SpatialIndex {
    /// Create an empty spatial index.
    #[inline]
    pub fn new() -> Self {
        SpatialIndex {
            tree: RTree::new(),
        }
    }

    /// Query all entities whose bounding boxes intersect the given region.
    ///
    /// Returns an iterator over entities (not entries) for convenience.
    ///
    /// # Arguments
    ///
    /// * `min` - Minimum corner of query region
    /// * `max` - Maximum corner of query region
    ///
    /// # Examples
    ///
    /// ```
    /// use bevy_ecs::prelude::*;
    /// use cypcb_world::{SpatialIndex, SpatialEntry};
    /// use cypcb_core::Point;
    ///
    /// let mut index = SpatialIndex::new();
    /// index.rebuild(vec![
    ///     SpatialEntry::new(Entity::from_raw(0), Point::from_mm(0.0, 0.0), Point::from_mm(10.0, 10.0), 1),
    /// ]);
    ///
    /// let found: Vec<_> = index.query_region(Point::from_mm(5.0, 5.0), Point::from_mm(15.0, 15.0)).collect();
    /// assert_eq!(found.len(), 1);
    /// ```
    pub fn query_region(&self, min: Point, max: Point) -> impl Iterator<Item = Entity> + '_ {
        let envelope = AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .map(|e| e.entity)
    }

    /// Query all entries (with full metadata) in a region.
    ///
    /// Use this when you need layer information or bounding boxes.
    pub fn query_region_entries(&self, min: Point, max: Point) -> impl Iterator<Item = &SpatialEntry> {
        let envelope = AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]);
        self.tree.locate_in_envelope_intersecting(&envelope)
    }

    /// Query entities at a specific point.
    ///
    /// Returns all entities whose bounding box contains the point.
    pub fn query_point(&self, point: Point) -> impl Iterator<Item = Entity> + '_ {
        let p = [point.x.0, point.y.0];
        let envelope = AABB::from_point(p);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .map(|e| e.entity)
    }

    /// Query entities at a point, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `point` - The query point
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_point_on_layers(
        &self,
        point: Point,
        layer_mask: u32,
    ) -> impl Iterator<Item = Entity> + '_ {
        let p = [point.x.0, point.y.0];
        let envelope = AABB::from_point(p);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .filter(move |e| e.layers_overlap(layer_mask))
            .map(|e| e.entity)
    }

    /// Query entities in a region, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `min` - Minimum corner of query region
    /// * `max` - Maximum corner of query region
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_region_on_layers(
        &self,
        min: Point,
        max: Point,
        layer_mask: u32,
    ) -> impl Iterator<Item = Entity> + '_ {
        let envelope = AABB::from_corners([min.x.0, min.y.0], [max.x.0, max.y.0]);
        self.tree
            .locate_in_envelope_intersecting(&envelope)
            .filter(move |e| e.layers_overlap(layer_mask))
            .map(|e| e.entity)
    }

    /// Rebuild the spatial index with new entries.
    ///
    /// Uses bulk loading for optimal tree structure.
    /// This is more efficient than incremental insertion for large batches.
    ///
    /// # Arguments
    ///
    /// * `entries` - Vector of spatial entries to index
    pub fn rebuild(&mut self, entries: Vec<SpatialEntry>) {
        self.tree = RTree::bulk_load(entries);
    }

    /// Clear the spatial index.
    pub fn clear(&mut self) {
        self.tree = RTree::new();
    }

    /// Check if the index is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.tree.size() == 0
    }

    /// Get the number of entries in the index.
    #[inline]
    pub fn len(&self) -> usize {
        self.tree.size()
    }

    /// Iterate over all entries in the index.
    pub fn iter(&self) -> impl Iterator<Item = &SpatialEntry> {
        self.tree.iter()
    }
}

impl std::fmt::Debug for SpatialIndex {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SpatialIndex")
            .field("entries", &self.tree.size())
            .finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_entry(id: u32, min_mm: (f64, f64), max_mm: (f64, f64), layers: u32) -> SpatialEntry {
        SpatialEntry::new(
            Entity::from_raw(id),
            Point::from_mm(min_mm.0, min_mm.1),
            Point::from_mm(max_mm.0, max_mm.1),
            layers,
        )
    }

    #[test]
    fn test_empty_index() {
        let index = SpatialIndex::new();
        assert!(index.is_empty());
        assert_eq!(index.len(), 0);
    }

    #[test]
    fn test_rebuild_and_len() {
        let mut index = SpatialIndex::new();
        let entries = vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (20.0, 20.0), (30.0, 30.0), 1),
        ];
        index.rebuild(entries);

        assert!(!index.is_empty());
        assert_eq!(index.len(), 2);
    }

    #[test]
    fn test_query_region_finds_intersecting() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (5.0, 5.0), (15.0, 15.0), 1),
            make_entry(2, (100.0, 100.0), (110.0, 110.0), 1),
        ]);

        // Query overlapping region - should find entries 0 and 1
        let found: Vec<_> = index
            .query_region(Point::from_mm(4.0, 4.0), Point::from_mm(6.0, 6.0))
            .collect();
        assert_eq!(found.len(), 2);

        // Query region only overlapping entry 2
        let found: Vec<_> = index
            .query_region(Point::from_mm(105.0, 105.0), Point::from_mm(106.0, 106.0))
            .collect();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0], Entity::from_raw(2));
    }

    #[test]
    fn test_query_region_no_match() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![make_entry(0, (0.0, 0.0), (10.0, 10.0), 1)]);

        let found: Vec<_> = index
            .query_region(Point::from_mm(50.0, 50.0), Point::from_mm(60.0, 60.0))
            .collect();
        assert!(found.is_empty());
    }

    #[test]
    fn test_query_point() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (5.0, 5.0), (15.0, 15.0), 1),
        ]);

        // Point inside only entry 0
        let found: Vec<_> = index.query_point(Point::from_mm(2.0, 2.0)).collect();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0], Entity::from_raw(0));

        // Point inside both entries
        let found: Vec<_> = index.query_point(Point::from_mm(7.0, 7.0)).collect();
        assert_eq!(found.len(), 2);
    }

    #[test]
    fn test_layer_filtering() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 0b01), // Top only
            make_entry(1, (0.0, 0.0), (10.0, 10.0), 0b10), // Bottom only
            make_entry(2, (0.0, 0.0), (10.0, 10.0), 0b11), // Both
        ]);

        // Query top layer only
        let found: Vec<_> = index
            .query_region_on_layers(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 10.0),
                0b01,
            )
            .collect();
        assert_eq!(found.len(), 2); // Entries 0 and 2

        // Query bottom layer only
        let found: Vec<_> = index
            .query_region_on_layers(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 10.0),
                0b10,
            )
            .collect();
        assert_eq!(found.len(), 2); // Entries 1 and 2
    }

    #[test]
    fn test_entry_layer_methods() {
        let entry = make_entry(0, (0.0, 0.0), (10.0, 10.0), 0b101); // Layers 0 and 2

        assert!(entry.on_layer(0));
        assert!(!entry.on_layer(1));
        assert!(entry.on_layer(2));

        assert!(entry.layers_overlap(0b001));
        assert!(!entry.layers_overlap(0b010));
        assert!(entry.layers_overlap(0b111));
    }

    #[test]
    fn test_clear() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![make_entry(0, (0.0, 0.0), (10.0, 10.0), 1)]);
        assert!(!index.is_empty());

        index.clear();
        assert!(index.is_empty());
    }

    #[test]
    fn test_iter() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (20.0, 20.0), (30.0, 30.0), 1),
        ]);

        let entries: Vec<_> = index.iter().collect();
        assert_eq!(entries.len(), 2);
    }
}

//! Trace and via components for routing.
//!
//! These components represent copper traces and vias on the PCB.
//! Traces are polyline paths connecting pads, while vias are
//! drill holes that connect copper on different layers.
//!
//! # Architecture
//!
//! - [`TraceSegment`] - A single line segment (start to end point)
//! - [`Trace`] - A polyline path composed of segments, belonging to a net
//! - [`Via`] - A drill hole connecting layers, with annular ring
//! - [`TraceSource`] - Enum indicating if trace was manual or autorouted
//!
//! # Example
//!
//! ```
//! use cypcb_world::components::trace::{Trace, TraceSegment, TraceSource, Via};
//! use cypcb_world::{NetId, Layer};
//! use cypcb_core::{Nm, Point};
//!
//! // Create a trace with two segments
//! let segments = vec![
//!     TraceSegment::new(Point::from_mm(0.0, 0.0), Point::from_mm(5.0, 0.0)),
//!     TraceSegment::new(Point::from_mm(5.0, 0.0), Point::from_mm(5.0, 5.0)),
//! ];
//!
//! let trace = Trace {
//!     segments,
//!     width: Nm::from_mm(0.2),
//!     layer: Layer::TopCopper,
//!     net_id: NetId::new(0),
//!     locked: false,
//!     source: TraceSource::Manual,
//! };
//!
//! assert_eq!(trace.segments.len(), 2);
//! ```

use bevy_ecs::prelude::*;
use serde::{Deserialize, Serialize};

use cypcb_core::{Nm, Point};

use crate::components::electrical::NetId;
use crate::components::physical::Layer;

/// A single line segment of a trace (from start to end point).
///
/// TraceSegment is not a component - it's a data structure used within [`Trace`].
/// Each segment represents a straight line between two points.
///
/// # Example
///
/// ```
/// use cypcb_world::components::trace::TraceSegment;
/// use cypcb_core::Point;
///
/// let seg = TraceSegment::new(
///     Point::from_mm(0.0, 0.0),
///     Point::from_mm(10.0, 5.0),
/// );
///
/// // Calculate segment length
/// let length = seg.length();
/// assert!(length.0 > 0);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct TraceSegment {
    /// Start point of the segment.
    pub start: Point,
    /// End point of the segment.
    pub end: Point,
}

impl TraceSegment {
    /// Create a new trace segment from start to end point.
    #[inline]
    pub fn new(start: Point, end: Point) -> Self {
        TraceSegment { start, end }
    }

    /// Calculate the length of this segment in nanometers.
    ///
    /// Uses Euclidean distance formula: sqrt((x2-x1)^2 + (y2-y1)^2)
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::TraceSegment;
    /// use cypcb_core::{Nm, Point};
    ///
    /// // Horizontal segment, 10mm long
    /// let seg = TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 0.0),
    /// );
    /// assert_eq!(seg.length(), Nm::from_mm(10.0));
    ///
    /// // Vertical segment, 5mm long
    /// let seg2 = TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(0.0, 5.0),
    /// );
    /// assert_eq!(seg2.length(), Nm::from_mm(5.0));
    /// ```
    pub fn length(&self) -> Nm {
        let dx = self.end.x.0 - self.start.x.0;
        let dy = self.end.y.0 - self.start.y.0;

        // Use i128 to prevent overflow during squared calculation
        let dx_squared = (dx as i128) * (dx as i128);
        let dy_squared = (dy as i128) * (dy as i128);

        // sqrt of sum, rounded to nearest nanometer
        let sum = dx_squared + dy_squared;
        let length = (sum as f64).sqrt() as i64;

        Nm(length)
    }

    /// Get the midpoint of this segment.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::TraceSegment;
    /// use cypcb_core::Point;
    ///
    /// let seg = TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 10.0),
    /// );
    /// let mid = seg.midpoint();
    /// assert_eq!(mid, Point::from_mm(5.0, 5.0));
    /// ```
    pub fn midpoint(&self) -> Point {
        Point::new(
            Nm((self.start.x.0 + self.end.x.0) / 2),
            Nm((self.start.y.0 + self.end.y.0) / 2),
        )
    }
}

/// Indicates whether a trace was created manually or by an autorouter.
///
/// This is used to track the origin of traces for debugging and
/// to potentially apply different editing behaviors.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
pub enum TraceSource {
    /// Trace was manually defined in the DSL.
    #[default]
    Manual,
    /// Trace was generated by the autorouter.
    Autorouted,
}

/// A copper trace connecting pads on a PCB.
///
/// Traces are polyline paths composed of one or more [`TraceSegment`]s.
/// Each trace belongs to a specific net and has a fixed width and layer.
///
/// # Fields
///
/// - `segments`: The polyline path as a vector of segments
/// - `width`: Trace width in nanometers
/// - `layer`: Which copper layer the trace is on
/// - `net_id`: Which net this trace belongs to
/// - `locked`: If true, autorouter should not modify this trace
/// - `source`: Whether trace was manual or autorouted
///
/// # Example
///
/// ```
/// use cypcb_world::components::trace::{Trace, TraceSegment, TraceSource};
/// use cypcb_world::{NetId, Layer};
/// use cypcb_core::{Nm, Point};
///
/// let trace = Trace {
///     segments: vec![
///         TraceSegment::new(Point::from_mm(0.0, 0.0), Point::from_mm(10.0, 0.0)),
///     ],
///     width: Nm::from_mm(0.2),
///     layer: Layer::TopCopper,
///     net_id: NetId::new(0),
///     locked: true,
///     source: TraceSource::Manual,
/// };
///
/// assert!(trace.locked);
/// assert_eq!(trace.total_length(), Nm::from_mm(10.0));
/// ```
#[derive(Component, Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Trace {
    /// The polyline path as a vector of connected segments.
    pub segments: Vec<TraceSegment>,
    /// Trace width in nanometers.
    pub width: Nm,
    /// Which copper layer this trace is on.
    pub layer: Layer,
    /// The net this trace belongs to.
    pub net_id: NetId,
    /// If true, autorouter should not modify this trace.
    pub locked: bool,
    /// Origin of this trace (manual or autorouted).
    pub source: TraceSource,
}

impl Trace {
    /// Create a new trace with default values.
    ///
    /// Creates an empty trace on the top copper layer with 0.2mm width.
    ///
    /// # Arguments
    ///
    /// * `net_id` - The net this trace belongs to
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Trace;
    /// use cypcb_world::NetId;
    ///
    /// let trace = Trace::new(NetId::new(0));
    /// assert!(trace.segments.is_empty());
    /// assert!(!trace.locked);
    /// ```
    pub fn new(net_id: NetId) -> Self {
        Trace {
            segments: Vec::new(),
            width: Nm::from_mm(0.2), // Default 0.2mm trace width
            layer: Layer::TopCopper,
            net_id,
            locked: false,
            source: TraceSource::Manual,
        }
    }

    /// Add a segment to this trace.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::{Trace, TraceSegment};
    /// use cypcb_world::NetId;
    /// use cypcb_core::Point;
    ///
    /// let mut trace = Trace::new(NetId::new(0));
    /// trace.add_segment(TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(5.0, 0.0),
    /// ));
    /// assert_eq!(trace.segments.len(), 1);
    /// ```
    pub fn add_segment(&mut self, segment: TraceSegment) {
        self.segments.push(segment);
    }

    /// Calculate the total length of this trace.
    ///
    /// Sums the lengths of all segments.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::{Trace, TraceSegment};
    /// use cypcb_world::NetId;
    /// use cypcb_core::{Nm, Point};
    ///
    /// let mut trace = Trace::new(NetId::new(0));
    /// trace.add_segment(TraceSegment::new(
    ///     Point::from_mm(0.0, 0.0),
    ///     Point::from_mm(10.0, 0.0),
    /// ));
    /// trace.add_segment(TraceSegment::new(
    ///     Point::from_mm(10.0, 0.0),
    ///     Point::from_mm(10.0, 5.0),
    /// ));
    ///
    /// // Total: 10mm + 5mm = 15mm
    /// assert_eq!(trace.total_length(), Nm::from_mm(15.0));
    /// ```
    pub fn total_length(&self) -> Nm {
        let total: i64 = self.segments.iter().map(|s| s.length().0).sum();
        Nm(total)
    }

    /// Get the start point of this trace (first segment start).
    ///
    /// Returns `None` if the trace has no segments.
    pub fn start_point(&self) -> Option<Point> {
        self.segments.first().map(|s| s.start)
    }

    /// Get the end point of this trace (last segment end).
    ///
    /// Returns `None` if the trace has no segments.
    pub fn end_point(&self) -> Option<Point> {
        self.segments.last().map(|s| s.end)
    }

    /// Check if this trace is empty (has no segments).
    pub fn is_empty(&self) -> bool {
        self.segments.is_empty()
    }

    /// Get the number of segments in this trace.
    pub fn segment_count(&self) -> usize {
        self.segments.len()
    }
}

/// A via connecting copper layers through a drill hole.
///
/// Vias are plated through-holes that connect traces on different
/// copper layers. They have a drill diameter and an outer diameter
/// (annular ring).
///
/// # Fields
///
/// - `position`: Center position of the via
/// - `drill`: Drill hole diameter in nanometers
/// - `outer_diameter`: Total via diameter including annular ring
/// - `start_layer`: Upper layer connection
/// - `end_layer`: Lower layer connection
/// - `net_id`: Which net this via belongs to
/// - `locked`: If true, autorouter should not modify this via
///
/// # Example
///
/// ```
/// use cypcb_world::components::trace::Via;
/// use cypcb_world::{NetId, Layer};
/// use cypcb_core::{Nm, Point};
///
/// let via = Via {
///     position: Point::from_mm(5.0, 5.0),
///     drill: Nm::from_mm(0.3),
///     outer_diameter: Nm::from_mm(0.6),
///     start_layer: Layer::TopCopper,
///     end_layer: Layer::BottomCopper,
///     net_id: NetId::new(0),
///     locked: false,
/// };
///
/// assert_eq!(via.annular_ring(), Nm::from_mm(0.15));
/// ```
#[derive(Component, Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct Via {
    /// Center position of the via.
    pub position: Point,
    /// Drill hole diameter in nanometers.
    pub drill: Nm,
    /// Total via diameter including annular ring.
    pub outer_diameter: Nm,
    /// Upper layer connection.
    pub start_layer: Layer,
    /// Lower layer connection.
    pub end_layer: Layer,
    /// The net this via belongs to.
    pub net_id: NetId,
    /// If true, autorouter should not modify this via.
    pub locked: bool,
}

impl Via {
    /// Create a new via with default sizes.
    ///
    /// Creates a via connecting top and bottom copper with:
    /// - 0.3mm drill diameter
    /// - 0.6mm outer diameter
    ///
    /// # Arguments
    ///
    /// * `position` - Center position of the via
    /// * `net_id` - The net this via belongs to
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Via;
    /// use cypcb_world::NetId;
    /// use cypcb_core::Point;
    ///
    /// let via = Via::new(Point::from_mm(10.0, 10.0), NetId::new(0));
    /// assert!(!via.locked);
    /// ```
    pub fn new(position: Point, net_id: NetId) -> Self {
        Via {
            position,
            drill: Nm::from_mm(0.3),
            outer_diameter: Nm::from_mm(0.6),
            start_layer: Layer::TopCopper,
            end_layer: Layer::BottomCopper,
            net_id,
            locked: false,
        }
    }

    /// Calculate the annular ring width (distance from drill edge to via edge).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Via;
    /// use cypcb_world::NetId;
    /// use cypcb_core::{Nm, Point};
    ///
    /// let via = Via {
    ///     position: Point::from_mm(0.0, 0.0),
    ///     drill: Nm::from_mm(0.3),
    ///     outer_diameter: Nm::from_mm(0.6),
    ///     start_layer: cypcb_world::Layer::TopCopper,
    ///     end_layer: cypcb_world::Layer::BottomCopper,
    ///     net_id: NetId::new(0),
    ///     locked: false,
    /// };
    ///
    /// // Annular ring = (outer - drill) / 2 = (0.6 - 0.3) / 2 = 0.15mm
    /// assert_eq!(via.annular_ring(), Nm::from_mm(0.15));
    /// ```
    pub fn annular_ring(&self) -> Nm {
        Nm((self.outer_diameter.0 - self.drill.0) / 2)
    }

    /// Check if this via spans all copper layers (through-hole via).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::components::trace::Via;
    /// use cypcb_world::{NetId, Layer};
    /// use cypcb_core::Point;
    ///
    /// let via = Via::new(Point::from_mm(0.0, 0.0), NetId::new(0));
    /// assert!(via.is_through_hole()); // Default is top-to-bottom
    /// ```
    pub fn is_through_hole(&self) -> bool {
        self.start_layer == Layer::TopCopper && self.end_layer == Layer::BottomCopper
    }
}

