        trace.add_segment(TraceSegment::new(
            Point::from_mm(1.0, 2.0),
            Point::from_mm(3.0, 4.0),
        ));
        trace.add_segment(TraceSegment::new(
            Point::from_mm(3.0, 4.0),
            Point::from_mm(5.0, 6.0),
        ));

        assert_eq!(trace.start_point(), Some(Point::from_mm(1.0, 2.0)));
        assert_eq!(trace.end_point(), Some(Point::from_mm(5.0, 6.0)));
    }

    #[test]
    fn test_trace_empty() {
        let trace = Trace::new(NetId::new(0));

        assert!(trace.is_empty());
        assert_eq!(trace.start_point(), None);
        assert_eq!(trace.end_point(), None);
        assert_eq!(trace.total_length(), Nm(0));
    }

    #[test]
    fn test_via_creation() {
        let via = Via::new(Point::from_mm(10.0, 20.0), NetId::new(5));

        assert_eq!(via.position, Point::from_mm(10.0, 20.0));
        assert_eq!(via.drill, Nm::from_mm(0.3));
        assert_eq!(via.outer_diameter, Nm::from_mm(0.6));
        assert_eq!(via.start_layer, Layer::TopCopper);
        assert_eq!(via.end_layer, Layer::BottomCopper);
        assert_eq!(via.net_id, NetId::new(5));
        assert!(!via.locked);
    }

    #[test]
    fn test_via_annular_ring() {
        let via = Via {
            position: Point::from_mm(0.0, 0.0),
            drill: Nm::from_mm(0.3),
            outer_diameter: Nm::from_mm(0.6),
            start_layer: Layer::TopCopper,
            end_layer: Layer::BottomCopper,
            net_id: NetId::new(0),
            locked: false,
        };

        // (0.6 - 0.3) / 2 = 0.15mm
        assert_eq!(via.annular_ring(), Nm::from_mm(0.15));
    }

    #[test]
    fn test_via_is_through_hole() {
        let through_via = Via::new(Point::ORIGIN, NetId::new(0));
        assert!(through_via.is_through_hole());

        let blind_via = Via {
            position: Point::ORIGIN,
            drill: Nm::from_mm(0.2),
            outer_diameter: Nm::from_mm(0.4),
            start_layer: Layer::TopCopper,
            end_layer: Layer::Inner(1), // Not bottom
            net_id: NetId::new(0),
            locked: false,
        };
        assert!(!blind_via.is_through_hole());
    }

    #[test]
    fn test_trace_source_enum() {
        let manual = TraceSource::Manual;
        let auto = TraceSource::Autorouted;

        assert_ne!(manual, auto);
        assert_eq!(TraceSource::default(), TraceSource::Manual);
    }

    #[test]
    fn test_trace_locked() {
        let mut trace = Trace::new(NetId::new(0));
        trace.locked = true;

        assert!(trace.locked);
    }

    #[test]
    fn test_trace_with_different_layers() {
        let mut trace = Trace::new(NetId::new(0));
        trace.layer = Layer::BottomCopper;

        assert_eq!(trace.layer, Layer::BottomCopper);
    }

    #[test]
    fn test_trace_with_different_widths() {
        let mut trace = Trace::new(NetId::new(0));
        trace.width = Nm::from_mm(0.5);

        assert_eq!(trace.width, Nm::from_mm(0.5));
    }

    #[test]
    fn test_via_locked() {
        let mut via = Via::new(Point::ORIGIN, NetId::new(0));
        via.locked = true;

        assert!(via.locked);
    }

    #[test]
    fn test_trace_autorouted_source() {
        let mut trace = Trace::new(NetId::new(0));
        trace.source = TraceSource::Autorouted;

        assert_eq!(trace.source, TraceSource::Autorouted);
    }
}

//! Clearance checking rule.
//!
//! Detects copper features that are too close together for manufacturing.
//! Uses the spatial index for efficient O(log n) candidate selection.

use cypcb_core::{Nm, Point};
use cypcb_world::BoardWorld;
use cypcb_world::components::NetId;
use hashbrown::{HashMap, HashSet};
use rstar::AABB;

use crate::presets::DesignRules;
use crate::violation::DrcViolation;

use super::DrcRule;

/// Rule for checking minimum clearance between copper features.
///
/// This rule verifies that all copper features on the same layer maintain
/// at least the minimum clearance distance specified by the design rules.
///
/// # Algorithm
///
/// 1. Iterate over all spatial entries
/// 2. For each entry, expand its bounding box by min_clearance
/// 3. Query the spatial index for overlapping candidates
/// 4. Filter candidates:
///    - Skip self
///    - Skip different layers (no copper overlap possible)
///    - Skip already-checked pairs (canonical ordering)
/// 5. Calculate actual AABB distance
/// 6. Report violations if distance < min_clearance
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::rules::{ClearanceRule, DrcRule};
/// use cypcb_drc::presets::DesignRules;
/// use cypcb_world::BoardWorld;
///
/// let mut world = BoardWorld::new();
/// // ... populate world ...
///
/// let rules = DesignRules::jlcpcb_2layer();
/// let violations = ClearanceRule.check(&mut world, &rules);
///
/// for v in violations {
///     println!("Clearance violation at {:?}: {}", v.location, v.message);
/// }
/// ```
pub struct ClearanceRule;

impl DrcRule for ClearanceRule {
    fn name(&self) -> &'static str {
        "clearance"
    }

    fn check(&self, world: &mut BoardWorld, rules: &DesignRules) -> Vec<DrcViolation> {
        let mut violations = Vec::new();
        let min_clearance = rules.min_clearance;

        // Build entity -> NetId lookup for same-net exemption.
        // Entities on the same net (e.g. two pads both on VCC) should not
        // generate clearance violations — they're intentionally connected.
        let net_map: HashMap<u32, NetId> = {
            let ecs = world.ecs_mut();
            let mut query = ecs.query::<(bevy_ecs::entity::Entity, &NetId)>();
            query.iter(ecs).map(|(e, n)| (e.index(), *n)).collect()
        };

        // Track checked pairs to avoid A-B and B-A duplicates
        let mut checked_pairs: HashSet<(u32, u32)> = HashSet::new();

        // Collect all entries first to avoid borrowing issues
        let entries: Vec<_> = world.spatial().iter().cloned().collect();

        for entry in &entries {
            // Expand bounding box by min_clearance to find candidates
            let query_min = Point::new(
                Nm(entry.envelope.lower()[0] - min_clearance.0),
                Nm(entry.envelope.lower()[1] - min_clearance.0),
            );
            let query_max = Point::new(
                Nm(entry.envelope.upper()[0] + min_clearance.0),
                Nm(entry.envelope.upper()[1] + min_clearance.0),
            );

            // Phase 1: R*-tree query for candidates
            for candidate in world.spatial().query_region_entries(query_min, query_max) {
                // Skip self
                if candidate.entity == entry.entity {
                    continue;
                }

                // Skip if different layers (no copper overlap possible)
                if !entry.layers_overlap(candidate.layer_mask) {
                    continue;
                }

                // Canonical pair ordering to avoid duplicate checks
                let pair = canonical_pair(entry.entity.index(), candidate.entity.index());
                if !checked_pairs.insert(pair) {
                    continue; // Already checked
                }

                // Same-net exemption: skip clearance check if both entities
                // belong to the same net (they're electrically connected)
                if let (Some(net_a), Some(net_b)) = (
                    net_map.get(&entry.entity.index()),
                    net_map.get(&candidate.entity.index()),
                ) {
                    if net_a == net_b {
                        continue;
                    }
                }

                // Phase 2: Calculate actual distance between AABBs
                let distance = aabb_distance(&entry.envelope, &candidate.envelope);

                if distance < min_clearance.0 {
                    let location = aabb_center(&entry.envelope);
                    violations.push(DrcViolation::clearance(
                        entry.entity,
                        candidate.entity,
                        Nm(distance),
                        min_clearance,
                        location,
                    ));
                }
            }
        }

        violations
    }
}

/// Create a canonical pair ordering to avoid duplicate checks.
///
/// Always returns (smaller, larger) to ensure A-B and B-A map to the same key.
#[inline]
fn canonical_pair(a: u32, b: u32) -> (u32, u32) {
    if a < b {
        (a, b)
    } else {
        (b, a)
    }
}

/// Calculate the minimum distance between two axis-aligned bounding boxes.
///
/// Returns 0 if the AABBs touch or overlap.
/// Uses i128 intermediates to prevent overflow during distance calculation.
fn aabb_distance(a: &AABB<[i64; 2]>, b: &AABB<[i64; 2]>) -> i64 {
    // Calculate gap in each dimension
    // If boxes overlap in a dimension, the gap is 0
    let dx = (a.lower()[0].max(b.lower()[0]) - a.upper()[0].min(b.upper()[0])).max(0);
    let dy = (a.lower()[1].max(b.lower()[1]) - a.upper()[1].min(b.upper()[1])).max(0);

    // Euclidean distance using i128 to prevent overflow
    let dx_sq = (dx as i128) * (dx as i128);
    let dy_sq = (dy as i128) * (dy as i128);
    ((dx_sq + dy_sq) as f64).sqrt() as i64
}

/// Calculate the center point of an AABB.
fn aabb_center(aabb: &AABB<[i64; 2]>) -> Point {
    Point::new(
        Nm((aabb.lower()[0] + aabb.upper()[0]) / 2),
        Nm((aabb.lower()[1] + aabb.upper()[1]) / 2),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use bevy_ecs::prelude::*;
    use cypcb_core::Point;
    use cypcb_world::SpatialEntry;
    use cypcb_world::components::NetId;

    use crate::ViolationKind;

    fn make_test_world_with_entries(entries: Vec<SpatialEntry>) -> BoardWorld {
        let mut world = BoardWorld::new();
        // Access the ECS world to directly populate the spatial index
        world.ecs_mut().resource_mut::<cypcb_world::SpatialIndex>().rebuild(entries);
        world
    }

    #[test]
    fn test_no_violation_when_far_apart() {
        // Two pads 10mm apart with 0.15mm clearance rule
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(10.0, 0.0),
                Point::from_mm(11.0, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert!(violations.is_empty(), "Should have no violations");
    }

    #[test]
    fn test_violation_when_too_close() {
        // Two pads 0.1mm apart with 0.15mm clearance rule
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(1.1, 0.0), // 0.1mm gap
                Point::from_mm(2.1, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer(); // 0.15mm clearance

        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Should have one violation");
        assert_eq!(violations[0].kind, ViolationKind::Clearance);
    }

    #[test]
    fn test_no_violation_different_layers() {
        // Two pads overlapping but on different layers
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01, // Top only
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(0.5, 0.5), // Overlapping position
                Point::from_mm(1.5, 1.5),
                0b10, // Bottom only
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();

        let violations = ClearanceRule.check(&mut world, &rules);

        assert!(
            violations.is_empty(),
            "Different layers should not cause violation"
        );
    }

    #[test]
    fn test_no_duplicate_violations() {
        // Ensure A-B violation is not reported twice as B-A
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(1.05, 0.0), // Very close (0.05mm gap)
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();

        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Should only report once");
    }

    #[test]
    fn test_aabb_distance_no_overlap() {
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([200, 0], [300, 100]);

        let dist = aabb_distance(&a, &b);
        assert_eq!(dist, 100, "Distance should be 100");
    }

    #[test]
    fn test_aabb_distance_touching() {
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([100, 0], [200, 100]);

        let dist = aabb_distance(&a, &b);
        assert_eq!(dist, 0, "Touching AABBs have zero distance");
    }

    #[test]
    fn test_aabb_distance_overlapping() {
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([50, 50], [150, 150]);

        let dist = aabb_distance(&a, &b);
        assert_eq!(dist, 0, "Overlapping AABBs have zero distance");
    }

    #[test]
    fn test_aabb_distance_diagonal() {
        // Two AABBs separated diagonally
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([200, 200], [300, 300]);

        let dist = aabb_distance(&a, &b);
        // Diagonal distance: sqrt(100^2 + 100^2) = sqrt(20000) = ~141
        let expected = ((100_i64 * 100 + 100 * 100) as f64).sqrt() as i64;
        assert_eq!(dist, expected, "Diagonal distance calculation");
    }

    #[test]
    fn test_canonical_pair_ordering() {
        assert_eq!(canonical_pair(1, 2), (1, 2));
        assert_eq!(canonical_pair(2, 1), (1, 2));
        assert_eq!(canonical_pair(5, 5), (5, 5));
    }

    #[test]
    fn test_aabb_center() {
        let aabb = AABB::from_corners([0, 0], [1000, 2000]);
        let center = aabb_center(&aabb);
        assert_eq!(center.x, Nm(500));
        assert_eq!(center.y, Nm(1000));
    }

    #[test]
    fn test_same_net_exemption() {
        // Two pads very close together but on the same net — should NOT violate
        let mut world = BoardWorld::new();
        let vcc = NetId::new(42);

        // Spawn real entities in the ECS with NetId components
        let e0 = world.ecs_mut().spawn(vcc).id();
        let e1 = world.ecs_mut().spawn(vcc).id();

        let entries = vec![
            SpatialEntry::new(
                e0,
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                e1,
                Point::from_mm(1.05, 0.0), // 0.05mm gap — would fail 0.15mm clearance
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        world.ecs_mut().resource_mut::<cypcb_world::SpatialIndex>().rebuild(entries);

        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert!(violations.is_empty(), "Same-net pads should be exempt from clearance check");
    }

    #[test]
    fn test_different_net_still_violates() {
        // Two pads close together on DIFFERENT nets — should violate
        let mut world = BoardWorld::new();

        // Spawn real entities with different NetIds
        let e0 = world.ecs_mut().spawn(NetId::new(1)).id();
        let e1 = world.ecs_mut().spawn(NetId::new(2)).id();

        let entries = vec![
            SpatialEntry::new(
                e0,
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                e1,
                Point::from_mm(1.05, 0.0), // 0.05mm gap
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        world.ecs_mut().resource_mut::<cypcb_world::SpatialIndex>().rebuild(entries);

        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Different-net pads should still violate");
    }

    #[test]
    fn test_no_net_still_violates() {
        // Entities without NetId component — should still be checked (legacy behavior)
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(1.05, 0.0),
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Entities without nets should still be checked");
    }
}

//! BoardWorld - High-level API for PCB board entities.
//!
//! Provides a clean wrapper around bevy_ecs::World with PCB-specific
//! operations for creating boards, spawning components, and querying.
//!
//! # Example
//!
//! ```
//! use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
//! use cypcb_core::Nm;
//!
//! // Create a new board world
//! let mut world = BoardWorld::new();
//!
//! // Set up the board
//! let board = world.set_board("MyBoard".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
//!
//! // Intern net names
//! let vcc = world.intern_net("VCC");
//! let gnd = world.intern_net("GND");
//!
//! // Spawn components
//! let r1 = world.spawn_component(
//!     RefDes::new("R1"),
//!     Value::new("10k"),
//!     Position::from_mm(10.0, 20.0),
//!     Rotation::ZERO,
//!     FootprintRef::new("0402"),
//!     NetConnections::new(),
//! );
//!
//! // Query the world
//! assert_eq!(world.component_count(), 1);
//! ```

use bevy_ecs::prelude::*;

use cypcb_core::{Nm, Point, Rect};

use crate::components::*;
use crate::registry::NetRegistry;
use crate::spatial::{SpatialEntry, SpatialIndex};

/// High-level wrapper around bevy_ecs::World for PCB board operations.
///
/// BoardWorld provides a clean, type-safe API for:
/// - Creating and configuring the board
/// - Spawning component entities
/// - Interning net names
/// - Spatial queries
/// - Direct ECS access when needed
///
/// # Architecture
///
/// Internally uses bevy_ecs::World with two resources:
/// - [`NetRegistry`]: For interning net names to integer IDs
/// - [`SpatialIndex`]: For efficient region-based queries
///
/// # Example
///
/// ```
/// use cypcb_world::BoardWorld;
/// use cypcb_core::Nm;
///
/// let mut world = BoardWorld::new();
///
/// // Create a 100x80mm 4-layer board
/// world.set_board("MyPCB".to_string(), (Nm::from_mm(100.0), Nm::from_mm(80.0)), 4);
///
/// // Get board info
/// if let Some((size, layers)) = world.board_info() {
///     println!("Board: {}x{}, {} layers", size.width, size.height, layers.count);
/// }
/// ```
pub struct BoardWorld {
    /// The underlying bevy_ecs World.
    world: World,
    /// Entity ID of the board (if set).
    board_entity: Option<Entity>,
}

impl BoardWorld {
    /// Create a new empty BoardWorld.
    ///
    /// Initializes the ECS world with:
    /// - Empty [`SpatialIndex`] resource
    /// - Empty [`NetRegistry`] resource
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// assert!(world.is_empty());
    /// ```
    pub fn new() -> Self {
        let mut world = World::new();
        world.insert_resource(SpatialIndex::new());
        world.insert_resource(NetRegistry::new());
        BoardWorld {
            world,
            board_entity: None,
        }
    }

    // ========================================================================
    // Board Management
    // ========================================================================

    /// Set the board properties, creating or updating the board entity.
    ///
    /// There can only be one board entity. Calling this multiple times
    /// will update the existing board entity.
    ///
    /// # Arguments
    ///
    /// * `name` - Board name/identifier
    /// * `size` - Board dimensions as (width, height) in nanometers
    /// * `layers` - Number of copper layers (2-32)
    ///
    /// # Returns
    ///
    /// The board entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::Nm;
    ///
    /// let mut world = BoardWorld::new();
    /// let board = world.set_board(
    ///     "TestBoard".to_string(),
    ///     (Nm::from_mm(100.0), Nm::from_mm(80.0)),
    ///     4,
    /// );
    /// ```
    pub fn set_board(&mut self, name: String, size: (Nm, Nm), layers: u8) -> Entity {
        let board_size = BoardSize::new(size.0, size.1);
        let layer_stack = LayerStack::new(layers);
        let name_component = crate::components::metadata::Name(name);

        if let Some(entity) = self.board_entity {
            // Update existing board
            let mut entity_mut = self.world.entity_mut(entity);
            entity_mut.insert((Board, board_size, layer_stack, name_component));
            entity
        } else {
            // Create new board
            let entity = self
                .world
                .spawn((Board, board_size, layer_stack, name_component))
                .id();
            self.board_entity = Some(entity);
            entity
        }
    }

    /// Get the board entity ID if one has been set.
    pub fn board_entity(&self) -> Option<Entity> {
        self.board_entity
    }

    /// Get board size and layer stack if a board has been set.
    ///
    /// # Returns
    ///
    /// Tuple of (BoardSize, LayerStack) if board exists, None otherwise.
    pub fn board_info(&self) -> Option<(BoardSize, LayerStack)> {
        let entity = self.board_entity?;
        let size = self.world.get::<BoardSize>(entity)?;
        let layers = self.world.get::<LayerStack>(entity)?;
        Some((*size, *layers))
    }

    /// Get the board name if one has been set.
    pub fn board_name(&self) -> Option<&str> {
        let entity = self.board_entity?;
        self.world
            .get::<crate::components::metadata::Name>(entity)
            .map(|n| n.0.as_str())
    }

    // ========================================================================
    // Component Spawning
    // ========================================================================

    /// Spawn a new component entity.
    ///
    /// # Arguments
    ///
    /// * `refdes` - Reference designator (R1, C1, U1, etc.)
    /// * `value` - Component value (10k, 100nF, etc.)
    /// * `position` - Position on board
    /// * `rotation` - Rotation angle
    /// * `footprint` - Footprint reference
    /// * `nets` - Net connections for each pin
    ///
    /// # Returns
    ///
    /// The spawned entity ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    /// ```
    pub fn spawn_component(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets))
            .id()
    }

    /// Spawn a component with a source span for error reporting.
    ///
    /// Same as [`spawn_component`](Self::spawn_component) but also attaches
    /// a [`SourceSpan`] for linking back to source file locations.
    pub fn spawn_component_with_span(
        &mut self,
        refdes: RefDes,
        value: Value,
        position: Position,
        rotation: Rotation,
        footprint: FootprintRef,
        nets: NetConnections,
        span: SourceSpan,
    ) -> Entity {
        self.world
            .spawn((refdes, value, position, rotation, footprint, nets, span))
            .id()
    }

    /// Spawn an entity with arbitrary components.
    ///
    /// Use this for custom entity types not covered by [`spawn_component`](Self::spawn_component).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Position};
    ///
    /// let mut world = BoardWorld::new();
    /// let entity = world.spawn_entity((
    ///     RefDes::new("J1"),
    ///     Position::from_mm(5.0, 5.0),
    /// ));
    /// ```
    pub fn spawn_entity<B: Bundle>(&mut self, bundle: B) -> Entity {
        self.world.spawn(bundle).id()
    }

    // ========================================================================
    // Net Registry
    // ========================================================================

    /// Intern a net name, returning its unique NetId.
    ///
    /// If the name has already been interned, returns the existing ID.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let mut world = BoardWorld::new();
    /// let vcc = world.intern_net("VCC");
    /// let vcc2 = world.intern_net("VCC");
    /// assert_eq!(vcc, vcc2); // Same ID
    /// ```
    pub fn intern_net(&mut self, name: &str) -> NetId {
        self.world.resource_mut::<NetRegistry>().intern(name)
    }

    /// Get the name for a NetId.
    ///
    /// Returns None if the ID is invalid.
    pub fn net_name(&self, id: NetId) -> Option<&str> {
        self.world.resource::<NetRegistry>().name(id)
    }

    /// Look up a NetId by name without interning.
    ///
    /// Returns None if the name has not been interned.
    pub fn get_net(&self, name: &str) -> Option<NetId> {
        self.world.resource::<NetRegistry>().get(name)
    }

    /// Get the number of interned nets.
    pub fn net_count(&self) -> usize {
        self.world.resource::<NetRegistry>().len()
    }

    /// Iterate over all interned nets.
    pub fn nets(&self) -> impl Iterator<Item = (NetId, &str)> {
        self.world.resource::<NetRegistry>().iter()
    }

    // ========================================================================
    // Spatial Index
    // ========================================================================

    /// Get a reference to the spatial index.
    ///
    /// Use this for direct spatial queries, iteration, or DRC checks.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    ///
    /// let world = BoardWorld::new();
    /// let spatial = world.spatial();
    /// assert!(spatial.is_empty());
    /// ```
    pub fn spatial(&self) -> &SpatialIndex {
        self.world.resource::<SpatialIndex>()
    }

    /// Rebuild the spatial index from current component positions.
    ///
    /// Call this after modifying component positions or spawning
    /// components to update the spatial index for efficient queries.
    ///
    /// # Arguments
    ///
    /// * `footprint_bounds` - Function to get bounds for a footprint name.
    ///   Used to calculate entity bounding boxes.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::BoardWorld;
    /// use cypcb_core::{Nm, Rect, Point};
    ///
    /// let mut world = BoardWorld::new();
    /// // ... spawn components ...
    ///
    /// // Rebuild with simple bounds
    /// world.rebuild_spatial_index(|_| Rect::from_center_size(
    ///     Point::ORIGIN,
    ///     (Nm::from_mm(1.0), Nm::from_mm(1.0)),
    /// ));
    /// ```
    pub fn rebuild_spatial_index<F>(&mut self, footprint_bounds: F)
    where
        F: Fn(&str) -> Rect,
    {
        let mut entries = Vec::new();

        // Query all positioned entities with footprints
        let mut query = self
            .world
            .query::<(Entity, &Position, &FootprintRef)>();

        for (entity, position, footprint) in query.iter(&self.world) {
            let bounds = footprint_bounds(footprint.as_str());
            let pos = position.0;

            // Translate bounds by position
            let min = Point::new(
                Nm(pos.x.0 + bounds.min.x.0),
                Nm(pos.y.0 + bounds.min.y.0),
            );
            let max = Point::new(
                Nm(pos.x.0 + bounds.max.x.0),
                Nm(pos.y.0 + bounds.max.y.0),
            );

            // Default to all layers for now (could be refined with pad layer info)
            let layer_mask = 0xFFFFFFFF;

            entries.push(SpatialEntry::new(entity, min, max, layer_mask));
        }

        self.world.resource_mut::<SpatialIndex>().rebuild(entries);
    }

    /// Query entities in a rectangular region.
    ///
    /// Returns all entities whose bounding boxes intersect the given bounds.
    ///
    /// # Note
    ///
    /// The spatial index must be rebuilt after component changes
    /// using [`rebuild_spatial_index`](Self::rebuild_spatial_index).
    pub fn query_region(&self, bounds: Rect) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region(bounds.min, bounds.max)
            .collect()
    }

    /// Query entities at a specific point.
    ///
    /// Returns all entities whose bounding boxes contain the point.
    pub fn query_point(&self, point: Point) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_point(point)
            .collect()
    }

    /// Query entities in a region, filtered by layer.
    ///
    /// # Arguments
    ///
    /// * `bounds` - The query region
    /// * `layer_mask` - Bit mask of layers to include
    pub fn query_region_on_layers(&self, bounds: Rect, layer_mask: u32) -> Vec<Entity> {
        self.world
            .resource::<SpatialIndex>()
            .query_region_on_layers(bounds.min, bounds.max, layer_mask)
            .collect()
    }

    // ========================================================================
    // Entity Queries
    // ========================================================================

    /// Get the number of component entities (excluding board).
    pub fn component_count(&mut self) -> usize {
        let mut query = self.world.query::<&RefDes>();
        query.iter(&self.world).count()
    }

    /// Check if the world is empty (no entities).
    pub fn is_empty(&self) -> bool {
        self.world.entities().len() == 0
    }

    /// Get a component from an entity.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// let refdes = world.get::<RefDes>(r1);
    /// assert_eq!(refdes.map(|r| r.as_str()), Some("R1"));
    /// ```
    pub fn get<T: Component>(&self, entity: Entity) -> Option<&T> {
        self.world.get::<T>(entity)
    }

    /// Get a mutable reference to a component.
    pub fn get_mut<T: Component>(&mut self, entity: Entity) -> Option<Mut<'_, T>> {
        self.world.get_mut::<T>(entity)
    }

    /// Check if an entity has a specific component.
    pub fn has<T: Component>(&self, entity: Entity) -> bool {
        self.world.get::<T>(entity).is_some()
    }

    /// Find an entity by its reference designator.
    ///
    /// # Example
    ///
    /// ```
    /// use cypcb_world::{BoardWorld, RefDes, Value, Position, Rotation, FootprintRef, NetConnections};
    ///
    /// let mut world = BoardWorld::new();
    /// let r1 = world.spawn_component(
    ///     RefDes::new("R1"),
    ///     Value::new("10k"),
    ///     Position::from_mm(10.0, 20.0),
    ///     Rotation::ZERO,
    ///     FootprintRef::new("0402"),
    ///     NetConnections::new(),
    /// );
    ///
    /// assert_eq!(world.find_by_refdes("R1"), Some(r1));
    /// assert_eq!(world.find_by_refdes("R2"), None);
    /// ```
    pub fn find_by_refdes(&mut self, refdes: &str) -> Option<Entity> {
        let mut query = self.world.query::<(Entity, &RefDes)>();
        query
            .iter(&self.world)
            .find(|(_, r)| r.as_str() == refdes)
            .map(|(e, _)| e)
    }

    /// Iterate over all components (entities with RefDes).
    ///
    /// Returns a vector of (Entity, RefDes clone, Position clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn components(&mut self) -> Vec<(Entity, RefDes, Position)> {
        let mut query = self.world.query::<(Entity, &RefDes, &Position)>();
        query
            .iter(&self.world)
            .map(|(e, r, p)| (e, r.clone(), *p))
            .collect()
    }

    /// Iterate over all zones.
    ///
    /// Returns a vector of (Entity, Zone clone) tuples.
    /// Uses clones to avoid lifetime issues with the query.
    pub fn zones(&mut self) -> Vec<(Entity, Zone)> {
        let mut query = self.world.query::<(Entity, &Zone)>();
        query
            .iter(&self.world)
            .map(|(e, z)| (e, z.clone()))
            .collect()
    }

    // ========================================================================
    // Direct ECS Access
    // ========================================================================

    /// Get direct access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced queries not covered by the BoardWorld API.
    pub fn ecs(&self) -> &World {
        &self.world
    }

    /// Get mutable access to the underlying bevy_ecs World.
    ///
    /// Use this for advanced operations not covered by the BoardWorld API.
    pub fn ecs_mut(&mut self) -> &mut World {
        &mut self.world
    }

    // ========================================================================
    // Serialization Helpers
    // ========================================================================

    /// Clear all entities and reset resources.
    pub fn clear(&mut self) {
        self.world.clear_entities();
        self.world.insert_resource(SpatialIndex::new());
        self.world.insert_resource(NetRegistry::new());
        self.board_entity = None;
    }
}

impl Default for BoardWorld {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_new_world_is_empty() {
        let mut world = BoardWorld::new();
        assert!(world.is_empty());
        assert_eq!(world.component_count(), 0);
        assert_eq!(world.net_count(), 0);
    }

    #[test]
    fn test_set_board() {
        let mut world = BoardWorld::new();
        let board = world.set_board(
            "TestBoard".to_string(),
            (Nm::from_mm(100.0), Nm::from_mm(80.0)),
            4,
        );

        assert_eq!(world.board_entity(), Some(board));
        assert_eq!(world.board_name(), Some("TestBoard"));

        let (size, layers) = world.board_info().unwrap();
        assert_eq!(size.width, Nm::from_mm(100.0));
        assert_eq!(size.height, Nm::from_mm(80.0));
        assert_eq!(layers.count, 4);
    }

    #[test]
    fn test_spawn_component() {
        let mut world = BoardWorld::new();
        let r1 = world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        assert_eq!(world.component_count(), 1);
        assert_eq!(world.get::<RefDes>(r1).map(|r| r.as_str()), Some("R1"));
        assert_eq!(world.get::<Value>(r1).map(|v| v.as_str()), Some("10k"));
    }

    #[test]
    fn test_intern_net() {
        let mut world = BoardWorld::new();

        let vcc = world.intern_net("VCC");
        let gnd = world.intern_net("GND");
        let vcc2 = world.intern_net("VCC");

        assert_eq!(vcc, vcc2);
        assert_ne!(vcc, gnd);
        assert_eq!(world.net_name(vcc), Some("VCC"));
        assert_eq!(world.net_count(), 2);
    }

    #[test]
    fn test_find_by_refdes() {
        let mut world = BoardWorld::new();

        let r1 = world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        let r2 = world.spawn_component(
            RefDes::new("R2"),
            Value::new("4.7k"),
            Position::from_mm(20.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        assert_eq!(world.find_by_refdes("R1"), Some(r1));
        assert_eq!(world.find_by_refdes("R2"), Some(r2));
        assert_eq!(world.find_by_refdes("R3"), None);
    }

    #[test]
    fn test_spatial_index() {
        let mut world = BoardWorld::new();

        // Spawn some components at known positions
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.spawn_component(
            RefDes::new("R2"),
            Value::new("10k"),
            Position::from_mm(50.0, 50.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Rebuild with simple 1mm x 1mm bounds
        world.rebuild_spatial_index(|_| {
            Rect::from_center_size(Point::ORIGIN, (Nm::from_mm(1.0), Nm::from_mm(1.0)))
        });

        // Query near R1
        let found = world.query_region(Rect::from_points(
            Point::from_mm(9.0, 9.0),
            Point::from_mm(11.0, 11.0),
        ));
        assert_eq!(found.len(), 1);

        // Query near R2
        let found = world.query_region(Rect::from_points(
            Point::from_mm(49.0, 49.0),
            Point::from_mm(51.0, 51.0),
        ));
        assert_eq!(found.len(), 1);

        // Query covering both
        let found = world.query_region(Rect::from_points(
            Point::from_mm(0.0, 0.0),
            Point::from_mm(100.0, 100.0),
        ));
        assert_eq!(found.len(), 2);

        // Query empty area
        let found = world.query_region(Rect::from_points(
            Point::from_mm(200.0, 200.0),
            Point::from_mm(300.0, 300.0),
        ));
        assert!(found.is_empty());
    }

    #[test]
    fn test_clear() {
        let mut world = BoardWorld::new();

        world.set_board("Test".to_string(), (Nm::from_mm(100.0), Nm::from_mm(100.0)), 2);
        world.intern_net("VCC");
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.clear();

        assert!(world.is_empty());
        assert_eq!(world.board_entity(), None);
        assert_eq!(world.net_count(), 0);
    }

    #[test]
    fn test_components_iterator() {
        let mut world = BoardWorld::new();

        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(10.0, 10.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        world.spawn_component(
            RefDes::new("C1"),
            Value::new("100nF"),
            Position::from_mm(20.0, 20.0),
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        let components = world.components();
        assert_eq!(components.len(), 2);
    }
}

/**
 * Layer colors and visibility definitions
 * KiCad-style colors for familiar PCB visualization
 */

// PCB electrical layer colors (fixed, not theme-dependent)
export const LAYER_COLORS = {
  top_copper: '#C83434',       // Red
  bottom_copper: '#3434C8',    // Blue
  top_silk: '#C8C8C8',         // Light gray
  bottom_silk: '#808080',      // Gray
  drill: '#FFFFFF',            // White (on dark) or black (on light)
  violation: '#FF0000',        // Red for DRC errors
  violation_ring: '#FF0000',   // Ring outline for violation markers
  via: '#808080',              // Gray for vias (between top/bottom)
  ratsnest: '#FFD700',         // Gold/Yellow for unrouted connections
} as const;

/**
 * Get current theme colors by reading CSS custom properties
 * These colors change based on the active theme (light/dark)
 */
export function getThemeColors() {
  const style = getComputedStyle(document.documentElement);
  return {
    background: style.getPropertyValue('--bg-canvas').trim() || '#ffffff',
    grid: style.getPropertyValue('--pcb-grid').trim() || '#e0e0e0',
    board_outline: style.getPropertyValue('--pcb-board-outline').trim() || '#cccc00',
    empty_text: style.getPropertyValue('--pcb-empty-text').trim() || '#666666',
    label: style.getPropertyValue('--pcb-label').trim() || '#333333',
  };
}

// Layer bit masks (match cypcb-world Layer enum)
export const LAYER_MASK = {
  TOP_COPPER: 0x00000001,
  BOTTOM_COPPER: 0x00000002,
  // Inner layers would be 0x00000004, 0x00000008, etc.
} as const;

export interface LayerVisibility {
  topCopper: boolean;
  bottomCopper: boolean;
}

/**
 * Create default layer visibility (all visible)
 */
export function createLayerVisibility(): LayerVisibility {
  return {
    topCopper: true,
    bottomCopper: true,
  };
}

/**
 * Toggle a specific layer's visibility
 */
export function toggleLayer(layers: LayerVisibility, layer: keyof LayerVisibility): LayerVisibility {
  return {
    ...layers,
    [layer]: !layers[layer],
  };
}

/**
 * Get color for a pad based on its layer mask and visibility settings
 * Returns null if the pad should not be drawn (layer hidden)
 */
export function getPadColor(layerMask: number, visibility: LayerVisibility): string | null {
  // Through-hole pads (on both layers)
  if ((layerMask & LAYER_MASK.TOP_COPPER) && (layerMask & LAYER_MASK.BOTTOM_COPPER)) {
    // Show if either layer visible
    if (visibility.topCopper || visibility.bottomCopper) {
      return '#C8C8C8'; // Gray for through-hole
    }
    return null;
  }

  // Top-only SMD
  if (layerMask & LAYER_MASK.TOP_COPPER) {
    return visibility.topCopper ? LAYER_COLORS.top_copper : null;
  }

  // Bottom-only SMD
  if (layerMask & LAYER_MASK.BOTTOM_COPPER) {
    return visibility.bottomCopper ? LAYER_COLORS.bottom_copper : null;
  }

  return null;
}

/**
 * Check if a layer mask is on the top layer
 */
export function isTopLayer(layerMask: number): boolean {
  return (layerMask & LAYER_MASK.TOP_COPPER) !== 0;
}

/**
 * Check if a layer mask is on the bottom layer
 */
export function isBottomLayer(layerMask: number): boolean {
  return (layerMask & LAYER_MASK.BOTTOM_COPPER) !== 0;
}

/**
 * Check if a layer mask is through-hole (both layers)
 */
export function isThroughHole(layerMask: number): boolean {
  return isTopLayer(layerMask) && isBottomLayer(layerMask);
}

/**
 * Get color for a trace based on its layer name and visibility settings
 * Returns null if the layer is not visible
 */
export function getTraceColor(layer: string, visibility: LayerVisibility): string | null {
  switch (layer) {
    case 'Top':
      return visibility.topCopper ? LAYER_COLORS.top_copper : null;
    case 'Bottom':
      return visibility.bottomCopper ? LAYER_COLORS.bottom_copper : null;
    default:
      // Inner layers - show if any copper layer is visible
      if (visibility.topCopper || visibility.bottomCopper) {
        return '#34C834'; // Green for inner layers
      }
      return null;
  }
}

//! Board snapshot types for JavaScript serialization.
//!
//! These types provide a flat, serializable view of the board state
//! suitable for transmission to JavaScript via serde-wasm-bindgen.
//!
//! All types use primitive types (i64, i32, u32, String) that serialize
//! cleanly to JavaScript numbers and strings.

use cypcb_drc::DrcViolation;
use serde::{Deserialize, Serialize};

/// Complete snapshot of the board state for rendering.
///
/// This is the main type returned by `PcbEngine::get_snapshot()`.
/// It contains all information needed to render the board in JavaScript.
#[derive(Debug, Serialize, Deserialize)]
pub struct BoardSnapshot {
    /// Board information (if a board has been defined).
    pub board: Option<BoardInfo>,
    /// All components on the board.
    pub components: Vec<ComponentInfo>,
    /// All nets and their connections.
    pub nets: Vec<NetInfo>,
    /// DRC violations found after loading.
    pub violations: Vec<ViolationInfo>,
    /// Copper traces (routed connections).
    pub traces: Vec<TraceInfo>,
    /// Vias (layer-to-layer connections).
    pub vias: Vec<ViaInfo>,
    /// Ratsnest lines (unrouted connections).
    pub ratsnest: Vec<RatsnestInfo>,
}

/// A DRC violation for display in the viewer.
///
/// This is a simplified representation of `cypcb_drc::DrcViolation`
/// suitable for JavaScript serialization and rendering.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ViolationInfo {
    /// Violation type (clearance, drill_size, unconnected_pin, etc.)
    pub kind: String,
    /// Board location X in nanometers.
    pub x_nm: i64,
    /// Board location Y in nanometers.
    pub y_nm: i64,
    /// Human-readable message.
    pub message: String,
}

impl ViolationInfo {
    /// Create a ViolationInfo from a DrcViolation.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_drc::{DrcViolation, ViolationKind};
    /// use cypcb_core::Point;
    /// use cypcb_world::Entity;
    /// use cypcb_render::ViolationInfo;
    ///
    /// let v = DrcViolation::unconnected_pin(
    ///     Entity::from_raw(1),
    ///     "1",
    ///     "R1",
    ///     Point::from_mm(10.0, 20.0),
    /// );
    /// let info = ViolationInfo::from_drc(&v);
    /// assert_eq!(info.kind, "unconnected-pin");
    /// assert!(info.message.contains("R1.1"));
    /// ```
    pub fn from_drc(v: &DrcViolation) -> Self {
        ViolationInfo {
            kind: format!("{}", v.kind),
            x_nm: v.location.x.0,
            y_nm: v.location.y.0,
            message: v.message.clone(),
        }
    }
}

/// Board-level information.
#[derive(Debug, Serialize, Deserialize)]
pub struct BoardInfo {
    /// Board name/identifier.
    pub name: String,
    /// Board width in nanometers.
    pub width_nm: i64,
    /// Board height in nanometers.
    pub height_nm: i64,
    /// Number of copper layers.
    pub layer_count: u8,
}

/// Component information for rendering.
#[derive(Debug, Serialize, Deserialize)]
pub struct ComponentInfo {
    /// Reference designator (R1, C1, U1, etc.).
    pub refdes: String,
    /// Component value (10k, 100nF, etc.).
    pub value: String,
    /// X position in nanometers.
    pub x_nm: i64,
    /// Y position in nanometers.
    pub y_nm: i64,
    /// Rotation in millidegrees (0-359999).
    pub rotation_mdeg: i32,
    /// Footprint name/identifier.
    pub footprint: String,
    /// Pad definitions from the footprint.
    pub pads: Vec<PadInfo>,
}

/// Pad information for rendering.
///
/// Positions are relative to the component origin.
#[derive(Debug, Serialize, Deserialize)]
pub struct PadInfo {
    /// Pad number/name (e.g., "1", "2", "A1", "VCC").
    pub number: String,
    /// X position relative to component origin, in nanometers.
    pub x_nm: i64,
    /// Y position relative to component origin, in nanometers.
    pub y_nm: i64,
    /// Pad width in nanometers.
    pub width_nm: i64,
    /// Pad height in nanometers.
    pub height_nm: i64,
    /// Shape as string: "circle", "rect", "roundrect", "oblong".
    pub shape: String,
    /// Copper layer bit mask (bit 0 = top, bit 1 = bottom, bits 2-31 = inner).
    pub layer_mask: u32,
    /// Drill diameter in nanometers (None for SMD pads).
    pub drill_nm: Option<i64>,
}

/// Net information.
#[derive(Debug, Serialize, Deserialize)]
pub struct NetInfo {
    /// Net name.
    pub name: String,
    /// Net ID (internal identifier).
    pub id: u32,
    /// All pin connections to this net.
    pub connections: Vec<PinRef>,
}

/// Reference to a component pin.
#[derive(Debug, Serialize, Deserialize)]
pub struct PinRef {
    /// Component reference designator.
    pub component: String,
    /// Pin number/name.
    pub pin: String,
}

/// A single segment of a trace (line from start to end).
///
/// TraceSegmentInfo is the JavaScript-serializable version of
/// `cypcb_world::components::trace::TraceSegment`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceSegmentInfo {
    /// Start X coordinate in nanometers.
    pub start_x: f64,
    /// Start Y coordinate in nanometers.
    pub start_y: f64,
    /// End X coordinate in nanometers.
    pub end_x: f64,
    /// End Y coordinate in nanometers.
    pub end_y: f64,
}

/// Trace information for rendering.
///
/// Represents a copper trace as a polyline with a given width.
/// Used by the JavaScript renderer to draw routed connections.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TraceInfo {
    /// The polyline path as a vector of segments.
    pub segments: Vec<TraceSegmentInfo>,
    /// Trace width in nanometers.
    pub width: f64,
    /// Layer name ("Top" or "Bottom").
    pub layer: String,
    /// Net name this trace belongs to.
    pub net_name: String,
    /// Whether this trace is locked (manual, not to be modified).
    pub locked: bool,
}

/// Via information for rendering.
///
/// Represents a plated through-hole connecting copper layers.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ViaInfo {
    /// Center X coordinate in nanometers.
    pub x: f64,
    /// Center Y coordinate in nanometers.
    pub y: f64,
    /// Drill hole diameter in nanometers.
    pub drill: f64,
    /// Outer diameter (copper ring) in nanometers.
    pub outer_diameter: f64,
    /// Net name this via belongs to.
    pub net_name: String,
}

/// Ratsnest line information for rendering.
///
/// Represents an unrouted connection between two pins.
/// Shown as a thin line to indicate what still needs routing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RatsnestInfo {
    /// Start X coordinate in nanometers.
    pub start_x: f64,
    /// Start Y coordinate in nanometers.
    pub start_y: f64,
    /// End X coordinate in nanometers.
    pub end_x: f64,
    /// End Y coordinate in nanometers.
    pub end_y: f64,
    /// Net name this connection belongs to.
    pub net_name: String,
}

#[cfg(test)]
mod tests {
